private void BindPollPartForm(DataTable dtbData)
{
    this.dtbPollPartData = dtbData;
    rptList.DataSource = dtbData;
    rptList.DataBind();
}

private void ReloadQuestionAnswerData()
{
    if (this.PollID == null)
        return;

    POL_Plan objPlan = new POL_Plan();
    this.dtbDataQuestion = objPlan.GetDataTable("POL_Question_SearchForDo", "@PollID", this.PollID);
    this.dtbDataAnswer = objPlan.GetDataTable("POL_Answer_SearchForDo", "@PollID", this.PollID);
}

private bool HasMutualExclusivePollParts()
{
    return HasMutualExclusivePollParts(this.dtbPollPartData);
}

private bool HasMutualExclusivePollParts(DataTable dtbPart)
{
    if (dtbPart == null)
        return false;

    bool hasMemberPart = false;
    bool hasBcsPart = false;

    foreach (DataRow dr in dtbPart.Rows)
    {
        int pollPartId = Convert.ToInt32(dr["PollPartID"]);
        if (pollPartId == POLL_PART_CHOICE_MEMBER)
            hasMemberPart = true;
        if (pollPartId == POLL_PART_CHOICE_BCS)
            hasBcsPart = true;
    }

    return hasMemberPart && hasBcsPart;
}

private bool ShouldShowPollPart(int pollPartId)
{
    if (pollPartId == POLL_PART_ALWAYS)
        return true;

    if (pollPartId == POLL_PART_CHOICE_MEMBER || pollPartId == POLL_PART_CHOICE_BCS)
    {
        if (!HasMutualExclusivePollParts())
            return true;

        if (this.SelectedChoicePollPartID == null)
            return false;

        return pollPartId == this.SelectedChoicePollPartID.Value;
    }

    return true;
}

private void SetupPollPartChoicePanel(RadioButtonList rblPollPartChoice)
{
    if (rblPollPartChoice == null || this.dtbPollPartData == null)
        return;

    rblPollPartChoice.Items.Clear();

    foreach (DataRow dr in this.dtbPollPartData.Rows)
    {
        int pollPartId = Convert.ToInt32(dr["PollPartID"]);
        if (pollPartId == POLL_PART_CHOICE_MEMBER || pollPartId == POLL_PART_CHOICE_BCS)
        {
            rblPollPartChoice.Items.Add(new ListItem(
                dr["PollPartName"].ToString(),
                pollPartId.ToString()));
        }
    }

    if (this.SelectedChoicePollPartID != null)
    {
        ListItem selectedItem = rblPollPartChoice.Items.FindByValue(this.SelectedChoicePollPartID.Value.ToString());
        if (selectedItem != null)
            selectedItem.Selected = true;
    }
}

private int? DetectSavedChoicePollPartID()
{
    if (this.dtbSavedDetail == null || this.dtbDataQuestion == null)
        return null;

    foreach (DataRow dr in this.dtbSavedDetail.Rows)
    {
        if (dr["QuestionID"] == DBNull.Value)
            continue;

        if (dr["DoMark"] == DBNull.Value || Convert.ToDecimal(dr["DoMark"]) == 0)
            continue;

        int questionId = Convert.ToInt32(dr["QuestionID"]);
        DataRow drQuestion = FindQuestionRow(this.dtbDataQuestion, questionId);
        if (drQuestion == null)
            continue;

        int pollPartId = Convert.ToInt32(drQuestion["PollPartID"]);
        if (pollPartId == POLL_PART_CHOICE_MEMBER || pollPartId == POLL_PART_CHOICE_BCS)
            return pollPartId;
    }

    return null;
}

protected void rblPollPartChoice_SelectedIndexChanged(object sender, EventArgs e)
{
    RadioButtonList rblPollPartChoice = sender as RadioButtonList;
    if (rblPollPartChoice == null || string.IsNullOrEmpty(rblPollPartChoice.SelectedValue))
        return;

    this.SelectedChoicePollPartID = Convert.ToInt32(rblPollPartChoice.SelectedValue);
    ReloadQuestionAnswerData();

    if (this.IsEditMode && this.DoneID != null)
        this.dtbSavedDetail = GetSavedDetailData(this.DoneID.Value);

    if (this.dtbPollPartData != null)
        BindPollPartForm(this.dtbPollPartData);

    udpForm.Update();
}

