private bool EnsureEditContext(bool showWarning)
{
    if (!this.IsEditMode)
        return !showWarning;

    if (this.DoneID != null)
        return true;

    if (this.PlanID == null)
    {
        if (showWarning)
            MsgBox.ShowWarning("Không xác định được phiếu cần cập nhật!");
        return false;
    }

    DataTable dtbDoneInfo = GetStudentDoneInfo();
    if (dtbDoneInfo == null || dtbDoneInfo.Rows.Count == 0)
    {
        if (showWarning)
            MsgBox.ShowWarning("Không xác định được phiếu cần cập nhật!");
        return false;
    }

    this.DoneID = Convert.ToInt64(dtbDoneInfo.Rows[0]["DoneID"]);
    if (this.PollID == null && dtbDoneInfo.Columns.Contains("PollID"))
        this.PollID = Convert.ToInt32(dtbDoneInfo.Rows[0]["PollID"]);

    if (this.dtbSavedDetail == null)
        this.dtbSavedDetail = GetSavedDetailData(this.DoneID.Value);

    return true;
}

