private void LoadEditEthicForm(DataRow drDoneInfo)
{
    long doneId = Convert.ToInt64(drDoneInfo["DoneID"]);
    int pollId = Convert.ToInt32(drDoneInfo["PollID"]);

    POL_Plan objPlan = new POL_Plan();
    objPlan.PlanID = this.PlanID;
    if (!objPlan.Get())
    {
        MsgBox.ShowError("Không tồn tại kế hoạch rèn luyện!");
        return;
    }

    //if (!objPlan.IsActived)
    //{
    //    MsgBox.ShowWarning("Kế hoạch rèn luyện chưa được kích hoạt!");
    //    return;
    //}

    lblPlanName.Text = objPlan.PlanName.Replace("\r\n", "<br>");

    if (User != null)
        lblPersonInfo.Text = string.Format("THỰC HIỆN BỞI: {0} ({1})", User.UserName, User.FullName);

    pnlStudentInfo.Visible = true;

    DataTable dtbData = objPlan.GetDataTable("POL_PollPart_SearchForDo", "@PollID", pollId);
    this.dtbDataQuestion = objPlan.GetDataTable("POL_Question_SearchForDo", "@PollID", pollId);
    this.dtbDataAnswer = objPlan.GetDataTable("POL_Answer_SearchForDo", "@PollID", pollId);
    this.dtbSavedDetail = GetSavedDetailData(doneId);

    if (User != null && WebGlobal.StudentID > 0)
    {
        Session["dtbStudentInfo"] = objPlan.GetDataTable("SIM_Student_GetInfo", "@StudentID", WebGlobal.StudentID);
    }

    if (dtbData != null)
    {
        if (this.dtbSavedDetail == null || this.dtbSavedDetail.Rows.Count == 0)
        {
            MsgBox.ShowError("Không tìm thấy chi tiết phiếu đánh giá để chỉnh sửa!");
            return;
        }

        this.DoneID = doneId;
        this.IsEditMode = true;
        this.PollID = pollId;
        this.SelectedChoicePollPartID = DetectSavedChoicePollPartID();
        BindPollPartForm(dtbData);
        pnlForm.Visible = true;
        pnlEditInfo.Visible = true;
        btnSave.Visible = true;
        btnSave.Text = "CẬP NHẬT ĐÁNH GIÁ";
    }
    else
    {
        MsgBox.ShowError("Việc tải dữ liệu chỉnh sửa bị lỗi!");
    }

    udpForm.Update();
}

