private DataTable BuildPartReadOnlyViewData(int pollPartId)
{
    if (this.dtbDataQuestion == null || this.DoneID == null)
        return null;

    DataTable dtbDetail = this.dtbSavedDetail;
    if (dtbDetail == null)
        dtbDetail = GetSavedDetailData(this.DoneID.Value);

    if (dtbDetail == null)
        return null;

    DataTable dtbQuestion = this.dtbDataQuestion.Copy();
    dtbQuestion.DefaultView.RowFilter = "PollPartID = " + pollPartId.ToString();
    dtbQuestion.DefaultView.Sort = "OrderIndex asc";
    dtbQuestion = dtbQuestion.DefaultView.ToTable();

    if (dtbQuestion.Rows.Count == 0)
        return null;

    DataTable dtbView = new DataTable();
    dtbView.Columns.Add("QuestionID", typeof(int));
    dtbView.Columns.Add("QuestionName", typeof(string));
    dtbView.Columns.Add("OrderIndex", typeof(int));
    dtbView.Columns.Add("MaxMark", typeof(string));
    dtbView.Columns.Add("StudentMark", typeof(decimal));
    dtbView.Columns.Add("DoneDetailID", typeof(long));

    foreach (DataRow drQuestion in dtbQuestion.Rows)
    {
        if (drQuestion["QuestionID"] == DBNull.Value)
            continue;

        int questionId = Convert.ToInt32(drQuestion["QuestionID"]);
        DataRow drDetail = FindDetailRow(dtbDetail, questionId);
        if (drDetail == null)
            continue;

        decimal studentMark = 0;
        if (drDetail["DoMark"] != DBNull.Value)
            studentMark = Convert.ToDecimal(drDetail["DoMark"]);

        int orderIndex = Convert.ToInt32(drDetail["OrderIndex"]);
        string maxMark = string.Empty;
        if (drQuestion.Table.Columns.Contains("Mark") && drQuestion["Mark"] != DBNull.Value)
            maxMark = drQuestion["Mark"].ToString();

        long doneDetailId = 0;
        if (drDetail.Table.Columns.Contains("DoneDetailID") && drDetail["DoneDetailID"] != DBNull.Value)
            doneDetailId = Convert.ToInt64(drDetail["DoneDetailID"]);

        dtbView.Rows.Add(
            questionId,
            drQuestion["QuestionName"].ToString(),
            orderIndex,
            maxMark,
            studentMark,
            doneDetailId);
    }

    return dtbView;
}

private decimal CalculateSavedTotalMark(long doneId, int pollId)
{
    ReloadQuestionAnswerData();
    DataTable dtbDetail = GetSavedDetailData(doneId);
    if (dtbDetail == null || this.dtbDataQuestion == null)
        return 0;

    int? savedChoicePollPartId = DetectSavedChoicePollPartID(this.dtbDataQuestion, dtbDetail);
    decimal totalStudent = 0;

    foreach (DataRow dr in dtbDetail.Rows)
    {
        if (dr["QuestionID"] == DBNull.Value || dr["DoMark"] == DBNull.Value)
            continue;

        int questionId = Convert.ToInt32(dr["QuestionID"]);
        DataRow drQuestion = FindQuestionRow(this.dtbDataQuestion, questionId);
        if (drQuestion == null)
            continue;

        int pollPartId = Convert.ToInt32(drQuestion["PollPartID"]);
        if (!ShouldIncludeSavedPollPart(pollPartId, savedChoicePollPartId))
            continue;

        totalStudent += Convert.ToDecimal(dr["DoMark"]);
    }

    return totalStudent;
}

private bool ShouldIncludeSavedPollPart(int pollPartId, int? savedChoicePollPartId)
