#endregion

#region POLL PART FILTER
private bool IsAlwaysVisiblePollPart(int pollPartId)
{
    return pollPartId == POLL_PART_ALWAYS || pollPartId == POLL_PART_AFTER;
}

private bool HasMutualExclusivePollParts(DataTable dtbPollPart)
{
    if (dtbPollPart == null)
        return false;

    bool hasMemberPart = false;
    bool hasBcsPart = false;

    foreach (DataRow dr in dtbPollPart.Rows)
    {
        int pollPartId = Convert.ToInt32(dr["PollPartID"]);
        if (pollPartId == POLL_PART_CHOICE_MEMBER)
            hasMemberPart = true;
        if (pollPartId == POLL_PART_CHOICE_BCS)
            hasBcsPart = true;
    }

    return hasMemberPart && hasBcsPart;
}

private bool ShouldIncludePollPart(int pollPartId, int? savedChoicePollPartId, bool hasMutualExclusiveParts)
{
    if (IsAlwaysVisiblePollPart(pollPartId))
        return true;

    if (pollPartId == POLL_PART_CHOICE_MEMBER || pollPartId == POLL_PART_CHOICE_BCS)
    {
        if (!hasMutualExclusiveParts)
            return true;

        if (savedChoicePollPartId == null)
            return false;

        return pollPartId == savedChoicePollPartId.Value;
    }

    return true;
}

private DataRow FindQuestionRow(DataTable dtbQuestion, int questionId)
{
    if (dtbQuestion == null)
        return null;

    foreach (DataRow dr in dtbQuestion.Rows)
    {
        if (dr["QuestionID"] == DBNull.Value)
            continue;

        if (Convert.ToInt32(dr["QuestionID"]) == questionId)
            return dr;
    }

    return null;
}

private int GetPollPartIdFromReportRow(DataRow drReport, DataTable dtbQuestion)
{
    if (drReport.Table.Columns.Contains("PollPartID") && drReport["PollPartID"] != DBNull.Value)
        return Convert.ToInt32(drReport["PollPartID"]);

    if (dtbQuestion == null || !drReport.Table.Columns.Contains("QuestionID") || drReport["QuestionID"] == DBNull.Value)
        return 0;

    DataRow drQuestion = FindQuestionRow(dtbQuestion, Convert.ToInt32(drReport["QuestionID"]));
    if (drQuestion == null || drQuestion["PollPartID"] == DBNull.Value)
        return 0;

    return Convert.ToInt32(drQuestion["PollPartID"]);
}

private int? DetectSavedChoicePollPartId(DataTable dtbQuestion, DataTable dtbReport)
{
    if (dtbReport == null)
        return null;

    foreach (DataRow dr in dtbReport.Rows)
    {
        int pollPartId = GetPollPartIdFromReportRow(dr, dtbQuestion);
        if (pollPartId == POLL_PART_CHOICE_MEMBER || pollPartId == POLL_PART_CHOICE_BCS)
            return pollPartId;
    }

    return null;
}

private int GetQuestionOrderIndex(DataRow drReport, DataTable dtbQuestion)
{
    if (drReport.Table.Columns.Contains("OrderIndex") && drReport["OrderIndex"] != DBNull.Value)
        return Convert.ToInt32(drReport["OrderIndex"]);

    if (dtbQuestion == null || !drReport.Table.Columns.Contains("QuestionID") || drReport["QuestionID"] == DBNull.Value)
        return 0;

    DataRow drQuestion = FindQuestionRow(dtbQuestion, Convert.ToInt32(drReport["QuestionID"]));
    if (drQuestion == null || drQuestion["OrderIndex"] == DBNull.Value)
        return 0;

    return Convert.ToInt32(drQuestion["OrderIndex"]);
}

private DataTable FilterEthicReportData(DataTable dtbData, string planId)
{
    if (dtbData == null || dtbData.Rows.Count == 0)
        return dtbData;

    POL_Plan objPlan = new POL_Plan();
    objPlan.PlanID = Convert.ToInt32(planId);
    if (!objPlan.Get())
        return dtbData;

    int pollId = objPlan.PollID.Value;
    DataTable dtbQuestion = objPlan.GetDataTable("POL_Question_SearchForDo", "@PollID", pollId);
    DataTable dtbPollPart = objPlan.GetDataTable("POL_PollPart_SearchForDo", "@PollID", pollId);

    if (!HasMutualExclusivePollParts(dtbPollPart))
        return dtbData;

    if (dtbQuestion == null && !dtbData.Columns.Contains("PollPartID"))
        return dtbData;

    int? savedChoicePollPartId = DetectSavedChoicePollPartId(dtbQuestion, dtbData);

    Dictionary<int, int> pollPartOrder = new Dictionary<int, int>();
    if (dtbPollPart != null)
    {
        int order = 0;
        foreach (DataRow drPart in dtbPollPart.Rows)
        {
            pollPartOrder[Convert.ToInt32(drPart["PollPartID"])] = order;
            order++;
        }
    }

    List<DataRow> filteredRows = new List<DataRow>();
    foreach (DataRow dr in dtbData.Rows)
    {
        int pollPartId = GetPollPartIdFromReportRow(dr, dtbQuestion);
        if (pollPartId <= 0)
        {
            filteredRows.Add(dr);
            continue;
        }

        if (ShouldIncludePollPart(pollPartId, savedChoicePollPartId, true))
            filteredRows.Add(dr);
    }

    filteredRows.Sort(delegate(DataRow rowA, DataRow rowB)
    {
        int pollPartA = GetPollPartIdFromReportRow(rowA, dtbQuestion);
        int pollPartB = GetPollPartIdFromReportRow(rowB, dtbQuestion);
        int orderA = pollPartOrder.ContainsKey(pollPartA) ? pollPartOrder[pollPartA] : 999;
        int orderB = pollPartOrder.ContainsKey(pollPartB) ? pollPartOrder[pollPartB] : 999;

        if (orderA != orderB)
            return orderA.CompareTo(orderB);

        int questionOrderA = GetQuestionOrderIndex(rowA, dtbQuestion);
        int questionOrderB = GetQuestionOrderIndex(rowB, dtbQuestion);
        return questionOrderA.CompareTo(questionOrderB);
    });

    DataTable dtbFiltered = dtbData.Clone();
    foreach (DataRow dr in filteredRows)
        dtbFiltered.ImportRow(dr);

    return dtbFiltered;
}
